N_values = range(1, 11)
results = {}

for N in N_values:
    # Calculate S(N)
    S_N = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # Using integer division // to calculate floor(ab / (N+1))
            S_N += (a * b) // (N + 1)

    # Calculate T(N)
    # T(N) = (N^3 - N^2 + 2) / 4
    T_N = (N**3 - N**2 + 2) / 4

    results[N] = (S_N, T_N)

# Print results for easy copying to notes
for N, (S_N, T_N) in results.items():
    print(f"N={N}: S(N)={S_N}, T(N)={T_N}")

def calculate_R(N):
    M = N + 1
    R_N = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            # Calculate fractional part {ab / M}
            # Note: (a * b) % M gives the remainder r. The fractional part is r/M.
            remainder = (a * b) % M
            R_N += remainder / M
    return R_N

def target_T_prime(N):
    # Target for R(N) is (N^2 - 1) / 2
    return (N**2 - 1) / 2

test_N = [3, 4, 7, 15] # N=3 (M=4, works), N=4 (M=5, prime, should fail), N=7 (M=8), N=15 (M=16)

print("--- Testing N values ---")
for N in test_N:
    R_N = calculate_R(N)
    Target = target_T_prime(N)
    print(f"N={N} (M={N+1}):")
    print(f"  Calculated R(N): {R_N}")
    print(f"  Required Target: {Target}")
    if abs(R_N - Target) < 1e-9:
        print("  MATCH FOUND!")
    else:
        print("  No match.")
